class Device {
    public void turnOn() { System.out.println("Device powered on"); }
}
class SmartPhone extends Device {
    public void makeCall(String number) {
        System.out.println("Dialing " + number);
    }
}
class Laptop extends Device {
    public void compileCode() {
        System.out.println("Compiling Java project...");
    }
}

public class DowncastDemo {
    public static void main(String[] args) {
        Device d1 = new SmartPhone();
        Device d2 = new Laptop();

        // 1. Safe guarded downcast
        if (d1 instanceof SmartPhone) {
            SmartPhone phone = (SmartPhone) d1;
            phone.makeCall("555-0199");
        }

        // 2. Unsafe downcast demo (uncomment to see crash)
        // SmartPhone fakePhone = (SmartPhone) d2; // Throws ClassCastException: Laptop cannot be cast to SmartPhone!

        // 3. Safe check for d2
        if (d2 instanceof Laptop) {
            Laptop laptop = (Laptop) d2;
            laptop.compileCode();
        }
    }
}

