interface Plugin {
    String getName();
}
interface ConfigurablePlugin extends Plugin {
    void configure(String configJson);
}

class LoggingPlugin implements ConfigurablePlugin {
    @Override public String getName() { return "ConsoleLogger"; }
    @Override public void configure(String configJson) {
        System.out.println("Logger configured with: " + configJson);
    }
}

class MetricsPlugin implements Plugin {
    @Override public String getName() { return "MetricsCollector"; }
}

public class PluginManager {
    public static void initializePlugin(Plugin p, String config) {
        System.out.println("Initializing plugin: " + p.getName());
        // Downcast to ConfigurablePlugin if supported
        if (p instanceof ConfigurablePlugin) {
            ConfigurablePlugin cp = (ConfigurablePlugin) p;
            cp.configure(config);
        } else {
            System.out.println("Plugin does not require custom configuration.");
        }
    }

    public static void main(String[] args) {
        initializePlugin(new LoggingPlugin(), "{\"level\": \"DEBUG\"}");
        initializePlugin(new MetricsPlugin(), "{}");
    }
}

