class Document {
    protected String title;
    public Document(String title) {
        this.title = title;
    }
    public String getTitle() { return title; }
}

class PdfDocument extends Document {
    private int numPages;
    public PdfDocument(String title, int numPages) {
        super(title);
        this.numPages = numPages;
    }
    public void renderVectorGraphics() {
        System.out.println("Rendering PDF vector graphics across " + numPages + " pages");
    }
}

class TextDocument extends Document {
    private String encoding;
    public TextDocument(String title, String encoding) {
        super(title);
        this.encoding = encoding;
    }
    public void applyWordWrap() {
        System.out.println("Applying word wrap with encoding " + encoding);
    }
}

class DocumentRenderer {
    public static void renderSpecialized(Document doc) {
        System.out.println("Processing document: " + doc.getTitle());
        if (doc instanceof PdfDocument) {
            PdfDocument pdf = (PdfDocument) doc;
            pdf.renderVectorGraphics();
        } else if (doc instanceof TextDocument) {
            TextDocument txt = (TextDocument) doc;
            txt.applyWordWrap();
        }
    }
}

public class DocApp {
    public static void main(String[] args) {
        DocumentRenderer.renderSpecialized(new PdfDocument("Whitepaper", 14));
        DocumentRenderer.renderSpecialized(new TextDocument("Notes", "UTF-8"));
    }
}

class AudioChannel {
    protected String channelName;
    public AudioChannel(String name) {
        this.channelName = name;
    }
    public String getChannelName() { return channelName; }
}

class VocalChannel extends AudioChannel {
    public VocalChannel(String name) { super(name); }
    public void autoTune(int pitchCorrection) {
        System.out.println("Autotuning " + channelName + " by " + pitchCorrection + " cents");
    }
}

class BassChannel extends AudioChannel {
    public BassChannel(String name) { super(name); }
    public void boostSubBass(double db) {
        System.out.println("Boosting sub-bass on " + channelName + " by " + db + " dB");
    }
}

class MixerDesk {
    public void processChannels(AudioChannel[] channels) {
        for (AudioChannel ch : channels) {
            if (ch instanceof VocalChannel) {
                VocalChannel v = (VocalChannel) ch;
                v.autoTune(25);
            } else if (ch instanceof BassChannel) {
                BassChannel b = (BassChannel) ch;
                b.boostSubBass(6.0);
            }
        }
    }
}

public class MixerApp {
    public static void main(String[] args) {
        AudioChannel[] desk = new AudioChannel[] {
            new VocalChannel("Lead Vocal"),
            new BassChannel("808 Sub")
        };
        MixerDesk mixer = new MixerDesk();
        mixer.processChannels(desk);
    }
}

