class Shape {}
class Circle extends Shape {
    private double radius;
    public Circle(double r) { this.radius = r; }
    public void printRadius() { System.out.println("Circle radius: " + radius); }
}
class Rectangle extends Shape {
    private double width, height;
    public Rectangle(double w, double h) { this.width = w; this.height = h; }
    public void printDimensions() { System.out.println("Rectangle: " + width + "x" + height); }
}

public class ShapeProcessor {
    public static void main(String[] args) {
        Shape[] shapes = new Shape[] {
            new Circle(5.0),
            new Rectangle(4.0, 6.0)
        };
        for (Shape s : shapes) {
            if (s instanceof Circle) {
                Circle c = (Circle) s;
                c.printRadius();
            } else if (s instanceof Rectangle) {
                Rectangle r = (Rectangle) s;
                r.printDimensions();
            }
        }
    }
}

interface Command {
    void execute();
}

class RestartCommand implements Command {
    @Override
    public void execute() {
        System.out.println("Executing system reboot");
    }
}

class BackupCommand implements Command {
    private String destination;
    public BackupCommand(String destination) {
        this.destination = destination;
    }
    @Override
    public void execute() {
        System.out.println("Executing backup to " + destination);
    }
    public void verifyChecksum() {
        System.out.println("Checksum verified for " + destination);
    }
}

class CommandRunner {
    public static void runAndVerify(Command[] batch) {
        for (Command cmd : batch) {
            cmd.execute();
            if (cmd instanceof BackupCommand) {
                BackupCommand bc = (BackupCommand) cmd;
                bc.verifyChecksum();
            }
        }
    }
}

public class CommandApp {
    public static void main(String[] args) {
        Command[] batch = new Command[] {
            new RestartCommand(),
            new BackupCommand("/mnt/nas/daily.bak")
        };
        CommandRunner.runAndVerify(batch);
    }
}
